import { Column, CreateDateColumn, Entity, Index, PrimaryGeneratedColumn } from 'typeorm';

/** The provider that vouched for the person (ADR 0008 D1/D2). */
export const IDENTITY_SUBJECT_KINDS = ['google', 'email', 'wallet'] as const;

export type IdentitySubjectKind = (typeof IDENTITY_SUBJECT_KINDS)[number];

/**
 * The stable CipherBox subject a verified provider identity maps to.
 *
 * The Core Kit derives its TSS key from `(verifier, verifierId)`, so this
 * row's `id` IS the vault: it rides the identity token's `sub`, is passed as
 * `verifierId`, and must never change for a given provider identity.
 *
 * Deliberately carries no `user_id`. The account still materializes at
 * `POST /auth/login`, keyed by the derived `publicKey` — this table's only job
 * is to yield a stable `verifierId`, so it cannot fork the account model. It is
 * also why several provider identities may point at one subject: that is what
 * linking a method means.
 */
@Entity('identity_subjects')
@Index('uq_identity_subjects_kind_identifier', ['kind', 'identifierHash'], { unique: true })
export class IdentitySubject {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ name: 'kind', type: 'varchar', length: 16 })
  kind: IdentitySubjectKind;

  /**
   * SHA-256 hex of the canonical provider identifier — Google's `sub`, the
   * normalized email, or the EIP-55 wallet address. Plaintext identifiers are
   * never stored, as in `auth_methods`.
   */
  @Column({ name: 'identifier_hash', type: 'varchar', length: 64 })
  identifierHash: string;

  @Column({ name: 'last_used_at', type: 'timestamptz', nullable: true })
  lastUsedAt: Date | null;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;
}
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Clock } from '../../common/clock';
import { IdentitySubject, IdentitySubjectKind } from '../entities/identity-subject.entity';
import { IdentityService } from './identity.service';

/**
 * Resolves a verified provider identity to its stable CipherBox subject id.
 *
 * Creates no `users` row: the account materializes at `POST /auth/login`
 * against the derived identity key, and nothing here knows that key yet.
 */
@Injectable()
export class IdentitySubjectService {
  constructor(
    @InjectRepository(IdentitySubject)
    private readonly subjects: Repository<IdentitySubject>,
    private readonly identityService: IdentityService,
    private readonly clock: Clock
  ) {}

  /**
   * The subject id for `identifier` under `kind`, minting one on first sight.
   *
   * Insert-then-read rather than check-then-insert: two concurrent first
   * logins for one identity both reach the insert, the unique index rejects
   * the loser, and the follow-up read returns the single winning row — so one
   * provider identity can never end up with two vaults.
   */
  async resolve(kind: IdentitySubjectKind, identifier: string): Promise<string> {
    const identifierHash = this.identityService.hashIdentifier(identifier);
    const now = this.clock.now();

    const existing = await this.subjects.findOne({ where: { kind, identifierHash } });
    if (existing) {
      await this.subjects.update({ id: existing.id }, { lastUsedAt: now });
      return existing.id;
    }

    const inserted = await this.subjects
      .createQueryBuilder()
      .insert()
      .into(IdentitySubject)
      .values({ kind, identifierHash, lastUsedAt: now })
      .orIgnore()
      .returning('id')
      .execute();
    const mintedId = (inserted.raw as { id: string }[])[0]?.id;
    if (mintedId) return mintedId;

    // Lost the insert race, so the winner's row is the one that counts.
    const stored = await this.subjects.findOne({ where: { kind, identifierHash } });
    if (!stored) {
      throw new InternalServerErrorException('Identity subject could not be resolved');
    }
    return stored.id;
  }
}

  /**
   * Link a SIWE wallet to the authenticated account (secondary method). The
   * identity challenge is re-proved first for the reason `unlinkAuthMethod`
   * states — adding a login method changes which keys open the account just as
   * removing one does, and the added method outlives the token that added it.
   */
  async siweLink(
    userId: string,
    publicKey: string,
    message: string,
    signature: `0x${string}`,
    challenge: string,
    challengeSignature: string
  ): Promise<void> {
    const canonicalKey = this.identityService.normalizePublicKey(publicKey);
    this.challengeService.consume(challenge, 'identity-link', { publicKey: canonicalKey });
    this.identityService.verifyChallengeSignature(challenge, challengeSignature, canonicalKey);

    const nonce = parseSiweMessage(message).nonce;
    if (!nonce) {
      throw new UnauthorizedException('Invalid SIWE message: missing nonce');
    }
    this.challengeService.consume(nonce, 'siwe-link', { publicKey: canonicalKey });
    const address = await this.siweService.verifySiweMessage(
      message,
      signature,
      nonce,
      SIWE_LINK_STATEMENT
    );

    const identifierHash = this.siweService.hashWalletAddress(address);
    const existing = await this.authMethodRepository.findOne({
      where: { kind: 'wallet', identifierHash },
    });
    if (existing && existing.userId !== userId) {
      throw new ConflictException('Wallet is already linked to another account');
    }

    await this.touchAuthMethod(userId, 'wallet', {
      identifierHash,
      identifierDisplay: this.siweService.truncateWalletAddress(address),
    });
  }

  /**
   * The account's login methods for the settings pane. The projection stops at
   * the display columns, so `identifier_hash` never leaves the database — the
   * hash is what makes a stored identifier unlinkable to the account that owns
   * it, and serving it would undo that.
   */
  }

  async logout(userId: string): Promise<void> {
    await this.tokenService.revokeAllForUser(userId);
  }

  private async touchAuthMethod(
    userId: string,
    kind: AuthMethod['kind'],
    identifiers: { identifierHash: string; identifierDisplay: string }
  ): Promise<void> {
    const existing = await this.authMethodRepository.findOne({
      where: { kind, identifierHash: identifiers.identifierHash },
    });
    if (existing) {
      existing.lastUsedAt = this.clock.now();
      await this.authMethodRepository.save(existing);
      return;
    }
    await this.authMethodRepository.save({
      userId,
      kind,
      identifierHash: identifiers.identifierHash,
      identifierDisplay: identifiers.identifierDisplay,
      lastUsedAt: this.clock.now(),
    });
  }
}

